// THE PLANE-SLOT SET: present73's claimed slot VAs, the fill set's member VAs in force, and the learner's distinct CB0s.
// build 0.0.551: split out so the learn site, the verb and the lines can read its SIZE; `set` null counts only (the verb, which
// is not under gXdLock, never writes the static array).
static uint64_t gLrSet[N48_LR_SET_MAX];   // under gXdLock (the pass / decide), like every other static here
static __attribute__((noinline)) uint32_t lr107_set_build(uint64_t *set)
{
    uint32_t n = 0u;
    for (uint32_t i = 0u; i < N48_P73_SLOTS && n < N48_LR_SET_MAX; i++)
        if (__atomic_load_n(&gP73.s[i].key, __ATOMIC_ACQUIRE)) { if (set) set[n] = gP73.s[i].va; n++; }
    for (uint32_t m = 0u; m < N48_FS_MEMBERS && m < gFs.members && n < N48_LR_SET_MAX; m++) { if (set) set[n] = gFs.member_va[m]; n++; }
    for (uint32_t i = 0u; i < gFsL.n && i < N48_FS_LEARN_NTH && n < N48_LR_SET_MAX; i++) { if (set) set[n] = gFsL.va[i]; n++; }
    return n;
}
static __attribute__((noinline)) uint32_t lr107_plane_now()
{
    const uint64_t fr = gXdC.judged + 1u;
    if (gLrF.gpFrame != fr || gLrF.cb0Frame != fr) return 0u;
    const uint32_t n = lr107_set_build(gLrSet);
    return n48_lr_plane_frame(1u, n48_lr_in_set(gLrF.cb0, gLrSet, n));
}
// build 0.0.538 (gfx_p94.h, gfx_p95.h): switches 94 and 95, OFF at boot (zero-initialised; each verb is its mode's only
// writer), and switch 94's log-only instruments (the per-second present outcome, the gate / retirement-observed stamps).
static n48_p94 gP94 {};
static n48_p95 gP95 {};
// The judged-frame poll's retirement site (under gXdLock): stamp the observation for the present's histogram. Log-only; OFF (73)
// one load and a return. (The expiry poll's site in ks_eop_at_expiry is left as 0.0.537 had it - its body is hash-pinned by
// gfx_fc89_test T34e - so a P it retired shows at the present as `retired, unstamped`.)
static __attribute__((noinline)) void p94_ret_note(uint32_t seq)
{
    if (!gP73On) return;
    n48_p94_note_ret(&gP94, &gP73, seq, latch_now_us());
}
// The judge's inputs for THIS frame, filled at the call site (file-scope: the submit path's frame must not grow).
static struct { uint64_t tgtVa, tgtVoff, fbStart, vramSize; uint32_t isP, commit, gateSeq, tgtN, tgtOk, tgtSys, tgtVoffOk, held;
                uint64_t keys[8]; } gP73J;
static __attribute__((noinline)) void p73_judge(const uint64_t *hVa, const uint64_t *hPage, const uint32_t *hRes,
                                                const uint32_t *hSys)
{
    const uint32_t nh = gP73J.held < 8u ? gP73J.held : 8u;
    if (gP73J.isP && gP73J.tgtN == 1u) {
        const uint64_t key = n48_p73_key(gP73J.tgtVa, gP73J.tgtVoff, gP73J.tgtOk, gP73J.tgtSys, gP73J.tgtVoffOk);
        const uint32_t i = n48_p73_gate_p(&gP73, key, gP73J.tgtVa, gP73J.commit, gP73J.gateSeq);
        if (i < N48_P73_SLOTS && gP73J.commit && gP73J.gateSeq)   // build 0.0.538 (log-only): the P's gate stamp
            n48_p94_note_gate(&gP94, i, gP73J.gateSeq, latch_now_us());
        if (i < N48_P73_SLOTS && !gP73.s[i].logged_p) {
            gP73.s[i].logged_p = 1u;
            HWLOG(N48_P73_PLINE_FMT, (unsigned long long)gP73J.tgtVa, (unsigned long long)key, i,
                  (unsigned long long)(gP73J.tgtVa & 0xfffull));
        }
        return;
    }
    // Not a P (or a P-shaped frame with other than one colour target): every held target that is a tracked plane is UNKNOWN,
    // and a frame with more targets than were held could have named any of them.
    for (uint32_t k = 0; k < nh; k++) {
        bool ok = false;
        const uint64_t voff = (hRes[k] && !hSys[k]) ? vmib_to_vram_off(hPage[k], gP73J.fbStart, gP73J.vramSize, ok) : 0ull;
        // build 0.0.517: the SAME key builder as the P's (page VRAM offset + the VA's offset in the
        // page); through 0.0.516 this omitted `va & 0xfff`, so a plane not at a page start could never be matched.
        gP73J.keys[k] = n48_p73_key(hVa[k], voff, hRes[k], hSys[k], ok ? 1u : 0u);
    }
    (void)n48_p73_gate_nonp(&gP73, gP73J.keys, nh);
    if (gP73J.tgtN > nh) n48_p73_invalidate_all(&gP73);
}
// hook_gfxCommitIB: the final outcome of the pending P of THIS submission (`committed` 1 only when the ring walk SPARED it).
