    const uint32_t r94 = (gP73On && p94_mode() == N48_P94_ON) ? p94_step(phys, presentNo) : (uint32_t)N48_P94_R_NONE;
    const uint64_t p86Promoted0 = gP86.r[N48_P86_R_PROMOTED];   // build 0.0.538 (log-only): did 86 promote at this present?
    // build 0.0.531 (switch 86, gfx_p86.h): 86 OFF this is n48_p73_should_copy, unchanged (plus the UNKNOWN split's counters);
    // 86 ON the present-time retirement re-check runs first (gXdLock by try-lock only, through kP86Io; one owned-slot fence read).
    const uint32_t copy = n48_p86_should_copy(gP73On ? 1u : 0u, p86_mode() == N48_P86_ON ? 1u : 0u, &gP73, &gP86, phys, &kP86Io,
                                              &why, &i);
