// build 0.0.521 Part E: dpg_perform made the copy 73 let through (clean or with a readback difference): the glass now shows
// that P, and later copies must be NEWER (n48_p73_delivered). Only while 73 is ON.
void hw_p73_delivered() { if (gP73On) n48_p73_delivered(&gP73); }
// The other scanout writer (Navi48AccelPeer.cpp flush-hook COPY) skipped a copy because the switch is ON.
void hw_p73_flush_held() { __atomic_fetch_add(&gP73.flushHeld, 1ull, __ATOMIC_RELAXED); }
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════
// build 0.0.538 ( PLAN item 2; gfx_p95.h) — SWITCH 95: REPLAY A HELD PRESENT. `95 | M << 8`: M 1 ON (= 351), M 2
// OFF (= 607, the default and the boot value), bare `95` reads; joins the continuous mid-arm guard. OFF (or 73 OFF) hw_p95_on
// answers 0 and dpg_perform asks switch 73's own question exactly as 0.0.537. ON: switch 73 answers THIS present first (the same
// hw_p73_present: 94, 86, Part E, 80 unchanged); a copy empties the table (every remembered present is older in present order);
// a hold is remembered (UNKNOWN on a PENDING slot), switch 94 (if ON) gets one lock-free step on the newest remembered plane
// still PENDING-spared, and n48_p95_pick may replay the PREVIOUS present (perform number - 1) if it was held and its P is now
// COMMITTED at the same seq and newer than the glass - refused while flip mode is blocked (navi48_fm_replay_blocked). The replay only swaps dpg_perform's copy source and
// geometry: the copy itself is the unchanged path after it (flip mode's n48_fm_present or the console copy), so no lock is added.
uint32_t hw_p95_on() { return (gP73On && __atomic_load_n(&gP95.on, __ATOMIC_ACQUIRE) == N48_P95_ON) ? 1u : 0u; }
// build 0.0.539 (; gfx_p95.h n48_p95_rid_*): the replay's identity - its slot, the picked seq, the slot's gate stamp
// (gP94.tm) - taken right after the pick; dpg_perform re-reads it after the copy returns (hw_p95_after_copy). Present thread only.
static n48_p95_rid gP95Rid {};
static __attribute__((noinline)) uint32_t p95_replay(uint64_t *phys, uint64_t *len, uint32_t *pw, uint32_t *ph, uint32_t *stride,
                                                     uint32_t *surfW, uint32_t *surfH, uint32_t *swz, uint64_t presentNo)
{
    const n48_p95_geom g = { *phys, *len, *pw, *ph, *stride, *surfW, *surfH, *swz };
    (void)n48_p95_remember(&gP95, &gP73, gP95Last.why, gP95Last.slot, &g, presentNo);
    if (p94_mode() == N48_P94_ON) {   // switch 94 at the replay: one lock-free step for the newest remembered PENDING-spared plane
        const uint64_t k = n48_p95_newest_pending(&gP95, &gP73);
        if (k && k != *phys) {
            gP94.atReplay++;
            if (p94_step(k, presentNo) == N48_P94_R_PROMOTED) n48_p94_sec_count(&gP94.sec, N48_P94_OC_P94);
        }
    }
    const uint32_t glass = gP73.deliveredOk ? gP73.lastDelivered : 0u;
    n48_p95_geom o {};
    uint32_t s = 0u;
    if (!n48_p95_pick(&gP95, &gP73, navi48_fm_replay_blocked(), presentNo, &o, &s)) return 0u;
    (void)n48_p95_rid_take(&gP95Rid, &gP73, gP94.tm, o.key, s, presentNo);   // build 0.0.539 M1: re-read after the copy
    *phys = o.key; *len = o.len; *pw = o.pw; *ph = o.ph; *stride = o.stride; *surfW = o.surfW; *surfH = o.surfH; *swz = o.swz;
    n48_p94_sec_count(&gP94.sec, N48_P94_OC_P95);
    if (gP95.lines < 8u) {
        gP95.lines++;
        HWLOG(N48_P95_LINE_FMT, (unsigned long long)presentNo, (unsigned long long)gP95.lastPresentNo, (unsigned long long)o.key, s,
              glass, gP95.lines);
    }
    return 1u;
}
// build 0.0.539: timed as a whole with the glass531 wrapper (wt_ticks / wt_note_since, as hw_p73_present):
// one exit, every answer noted in gWtP95.
uint32_t hw_p95_present(uint64_t *phys, uint64_t *len, uint32_t *pw, uint32_t *ph, uint32_t *stride, uint32_t *surfW,
                        uint32_t *surfH, uint32_t *swz, uint64_t presentNo)
{
    const uint64_t wt0 = wt_ticks();
    uint32_t r = 0u;
    if (!gP73On) r = 1u;                                     // 73 OFF: every present copies (the plain question's answer)
    else if (hw_p73_present(*phys, presentNo)) {             // 73 lets THIS present copy: every remembered present is older
        n48_p95_on_copy(&gP95);
        r = 1u;
    }
    else if (__atomic_load_n(&gP95.on, __ATOMIC_ACQUIRE) != N48_P95_ON) r = 0u;   // turned OFF between the two questions: hold
    else r = p95_replay(phys, len, pw, ph, stride, surfW, surfH, swz, presentNo);
    wt_note_since(&gWtP95, wt0);
    return r;
}
// RACED is an UPPER BOUND (gfx_p95.h n48_p95_rid_raced): a gate landing after the copy had finished is counted too.
// build 0.0.539: dpg_perform, right after its copy returned (beside hw_p73_delivered), for EVERY present:
// `made` 1 = the copy happened (clean or readback). Nothing pending (no replay at this present): one load. A replay of THIS present
// is re-checked (n48_p95_rid_raced: the slot's seq, state and gate stamp against the pick's) and a race counted and logged (capped
// at 8 lines); a replay whose copy was not made, or whose present never reached the copy (flip mode held it), is only counted.
// Decision-inert: the copy has happened; nothing here changes 73's table, Part E or the glass.
void hw_p95_after_copy(uint64_t presentNo, uint32_t made)
{
    if (!gP95Rid.used) return;
    const n48_p95_rid rid = gP95Rid;
    gP95Rid.used = 0u;
    if (rid.presentNo != presentNo) { gP95.recheckStale++; return; }
    if (!made) { gP95.recheckNoCopy++; return; }
    gP95.rechecked++;
    uint32_t seqNow = 0u, gseqNow = 0u, stNow = 0u;
    if (!n48_p95_rid_raced(&rid, &gP73, gP94.tm, &seqNow, &gseqNow, &stNow)) return;
    gP95.raced++;
    if (gP95.racedLines < 8u) {
        gP95.racedLines++;
        HWLOG(N48_P95_RACED_FMT, (unsigned long long)presentNo, (unsigned long long)rid.key, rid.seq, rid.slot, seqNow,
              n48_p73_state_name(stNow), rid.gseq, gseqNow, gP95.racedLines);
    }
}
// 0.0.369 — THE HEADLESS RECOGNISER'S SWITCH, OFF BY DEFAULT AND OFF AT BOOT. `accel gfxneuter 13 | 1 << 8` sets
// it, `13 | 2 << 8` clears it, `13` alone reads it. While it is 0 the kext behaves exactly as 0.0.368 did: xlat12_headless.c is
// linked in but never called, gXdBuild.kind is always N48_CM_KIND_ENCODER, and no frame's decision changes. On, and ONLY when
// xlat12_ib_segments found nothing, the setup halves are split into render passes; what the COMMIT gate then
// demands of them is gfx_commit.h's N48_CM_KIND_* paragraph, which is tighter than the encoder case, not looser.
