static __attribute__((noinline)) void rectfb_seg(uint32_t k, uint32_t from, uint32_t *st, xlat12_draw_stats *ds, const uint32_t *out,
                                                 uint32_t olen)
{
    if (k < N48_XV_MAX_SEGS) gRectFbSeg[k] = 0u;
    if (!ds->r2d_fallback) return;
    const uint32_t fst = *st;
    uint32_t last = 0u;
    const uint32_t nrect = fst ? 0u : xlat12_ib_rectlist_draws(out, olen, &last);
    const uint32_t act = n48_rfb_seg(&gRectFbS, __atomic_load_n(&gRectFbMode, __ATOMIC_RELAXED), 1u, fst, nrect, last, ds->r2d_on_op);
    if (act == N48_RFB_A_REFUSE) { *st = XLAT12_IB_ERR_VERIFY; ds->err_op = XLAT12_RFB_REFUSED; ds->err_reg = 0x30908u; }
    else if ((act == N48_RFB_A_KEEP || act == N48_RFB_A_WOULD) && k < N48_XV_MAX_SEGS) gRectFbSeg[k] = 1u;
    if (gRectFbArm != gXdShot.armed_at_us) { gRectFbArm = gXdShot.armed_at_us; gRectFbArmLines = 0u; }
    // build 0.0.548 item C: the 8 reason lines are spent only on fallbacks that CARRY a RECTLIST draw (nrect > 0: the ones ON
    // refuses); a refused or RECTLIST-free fallback is still counted above, it just prints no line.
    if (nrect != 0u && gRectFbArmLines < N48_RFB_LINES_MAX) {
        gRectFbArmLines++;
        gRectFbS.lines++;
        HWLOG(N48_RFB_SEG_FMT, N48_RFB_SEG_ARGS(gXdC.judged + 1u, k, from, ds, fst, nrect, last, act));
    }
}
// A frame the COMMIT gate answered yes for: its kept RECTLIST fallbacks (OFF / SHADOW: each one a half-cleared rectangle).
static __attribute__((noinline)) void rectfb_commit()
{
    uint64_t c = 0ull;
    for (uint32_t k = 0; k < N48_XV_MAX_SEGS; k++) c += gRectFbSeg[k];
    if (c) { gRectFbS.committed_frames++; gRectFbS.committed_segs += c; }
}
static __attribute__((noinline)) void rfb_report(const char *how)
{
    HWLOG(N48_RFB_FMT, N48_RFB_ARGS(__atomic_load_n(&gRectFbMode, __ATOMIC_RELAXED), how, &gRectFbS));
    HWLOG(N48_RFB_FMT2, N48_RFB_ARGS2(&gRectFbS));
}
