// Every byte of every recorded fill resolves, in THIS frame's own VM (`vm`: the page tables R1 walks), to VRAM - probed at the page
// table's own granularity (fix round (e), gfx_commit.h n48_nc_pages_walk): ONE probe per 64 KiB page where the L1 entry is itself the
// leaf, one per 4 KiB page under a sub-table. The probe is gfxc_page's own walk (root, L1 indexed by (va >> 16) & 0xfff, then the
// sub-table indexed by (va >> 12) & 0xf when bit 63 is clear) that also says which of the two it found; gfxc_page itself is unchanged.
// A fill past the XLAT12_NCLEAR_MAX recorded ones cannot be walked and refuses. 1 = every probe resolved to VRAM.
static uint32_t nclear_probe(void *ctx, uint64_t va, uint32_t *big)
{
    const GfxcVm &vm = *static_cast<const GfxcVm *>(ctx);
    *big = 0u;
    if (!vm.ok || va < vm.startVa) return 0u;
    uint32_t dw[2] = { 0, 0 };
    bool ok = false;
    const uint32_t rootIdx = (uint32_t)((va - vm.startVa) >> 28);
    if (rootIdx >= 512 || !navi48_vram_read_mm(vm.rootOff + (uint64_t)rootIdx * 8u, dw, 2)) return 0u;
    const uint64_t rootEnt = ((uint64_t)dw[1] << 32) | dw[0];
    if (!(rootEnt & 1ull)) return 0u;
    const uint64_t l1Base = vmib_to_vram_off(rootEnt & 0x0000FFFFFFFFF000ull, vm.fbStart, vm.vramSize, ok);
    if (!ok || !navi48_vram_read_mm(l1Base + ((va >> 16) & 0xfffull) * 8u, dw, 2)) return 0u;
    const uint64_t l1Ent = ((uint64_t)dw[1] << 32) | dw[0];
    if (!(l1Ent & 1ull)) return 0u;
    uint64_t leaf = l1Ent;
    if (!((l1Ent >> 63) & 1ull)) {
        const uint64_t subBase = vmib_to_vram_off(l1Ent & 0x0000FFFFFFFFFF80ull, vm.fbStart, vm.vramSize, ok);
        if (!ok || !navi48_vram_read_mm(subBase + ((va >> 12) & 0xfull) * 8u, dw, 2)) return 0u;
        leaf = ((uint64_t)dw[1] << 32) | dw[0];
    } else {
        *big = 1u;                                   // the L1 entry is the leaf: one 64 KiB mapping (gfxc_page's pageBase arithmetic)
    }
    if (!(leaf & 1ull)) return 0u;
    return ((leaf >> 1) & 1ull) ? 0u : 1u;          // system memory is refused: the target must be VRAM
}
static __attribute__((noinline)) uint32_t nclear_pages_ok(const GfxcVm &vm, const xlat12_draw_stats *ds)
{
    if (ds->nc_filled > XLAT12_NCLEAR_MAX) return 0u;
    for (uint32_t q = 0; q < ds->nc_filled; q++) {
        const uint64_t va = (uint64_t)ds->nc_va8[q] << 8;
        if (!n48_nc_pages_walk(&nclear_probe, const_cast<GfxcVm *>(&vm), va, ds->nc_len[q], &gNclearS.pages)) { gNclearS.pagesBad++; return 0u; }
    }
    return 1u;
}
// The segment's accounting and, for a TRANSLATED segment that filled, the kext's check (xlat12_ib_nclear_check over the candidate,
// then nclear_pages_ok); a failure refuses the segment XLAT12_IB_ERR_VERIFY / XLAT12_NCLEAR_BACKSTOP. The first
// N48_CM_NCLEAR_LINES fills of the boot are named.
static __attribute__((noinline)) void nclear_seg(const GfxcVm &vm, uint32_t k, uint32_t *st, xlat12_draw_stats *ds,
                                                 const uint32_t *out, uint32_t olen)
{
    gNclearS.filled += ds->nc_filled; gNclearS.bytes += ds->nc_bytes; gNclearS.pkts += ds->nc_pkts;
    gNclearS.refExtent += ds->nc_ref_extent; gNclearS.refRoom += ds->nc_ref_room; gNclearS.refRun += ds->nc_ref_run;
    gNclearS.refBarrier += ds->nc_ref_barrier; gNclearS.refMax += ds->nc_ref_max;   // fix round (a), (b)
    if (!ds->nc_filled) return;
    const uint32_t was = *st;
    if (!*st && (xlat12_ib_nclear_check(out, olen, ds) != 0u || !nclear_pages_ok(vm, ds))) {
        *st = XLAT12_IB_ERR_VERIFY; ds->err_op = XLAT12_NCLEAR_BACKSTOP; ds->err_reg = 0u; gNclearS.refused++;
    }
    for (uint32_t q = 0; q < ds->nc_filled && q < XLAT12_NCLEAR_MAX && gNclearS.lines < N48_CM_NCLEAR_LINES; q++) {
        gNclearS.lines++;
        const uint64_t va = (uint64_t)ds->nc_va8[q] << 8;
        HWLOG(N48_CM_NCLEAR_ONE_FMT, (unsigned long long)(gXdC.judged + 1u), k, (unsigned long long)va,
              (unsigned long long)(va + ds->nc_len[q]), ds->nc_len[q], (ds->nc_len[q] + XLAT12_NCLEAR_MAX_BYTES - 1u) / XLAT12_NCLEAR_MAX_BYTES,
              was ? "segment refused by the translator" : *st ? "REFUSED by the kext's check (packets or pages)" : "segment translated");
    }
}
