static const char *gfxsrc_pgmid_mode_str(uint32_t mode)
{
    return mode == N48_PGMID_MODE_T ? "T (head-first)"
         : mode == N48_PGMID_MODE_TM ? "T+M (per-pass memo)"
         : mode == N48_PGMID_MODE_SHADOW ? "SHADOW (T compared, HEAD's answer used)"
         : mode == N48_PGMID_MODE_SHADOW_M ? "SHADOW-M (T+M compared, HEAD's answer used)"
         : "OFF (default)";
}
