static __attribute__((noinline)) void p87_frame_end(uint64_t frame, uint32_t committed, uint64_t cb0) {
    const uint32_t out = n48_p87_frame_end(&gP87, frame, committed);
    for (uint32_t k = 0; k < out; k++) {
        const n48_p87_rec &e = gP87.r[k];
        const n48_p87_tsharp t = n48_p87_decode(e.rec);
        const uint32_t cbKnown = (e.st_seen & 1u) && ((e.st_seen & 2u) || !e.st_cb0_ext), winKnown = (e.st_seen & 0xCu) == 0xCu;
        HWLOG(N48_P87_FMT, (unsigned long long)frame, (unsigned long long)n48_p87_cb0_va(&e), cbKnown ? "" : " inh",
              n48_p87_sc_x(e.st_win_tl), n48_p87_sc_y(e.st_win_tl), n48_p87_sc_x(e.st_win_br), n48_p87_sc_y(e.st_win_br),
              winKnown ? "" : " inh", (unsigned long long)cb0, kN48P87Ids[e.id].name, kN48P87Ids[e.id].ident, e.at,
              e.tex, e.heap, (unsigned long long)t.base, t.w, t.h, t.fmt, t.sw, t.comp, t.wcomp, t.meta, e.rec[0], e.rec[1],
              e.rec[2], e.rec[3], e.rec[4], e.rec[5], e.rec[6], e.rec[7]);
    }
}
