// THE READBACK (DUMP): [off, off + len) of VRAM through the MM window, printed as hex lines (N48_P87_DUMP_LINE bytes each) between a
// HDR and an END line. Verb thread only; refused while a commit arm stands. File-scope buffer (the verb's frame stays small).
static uint32_t gP87Buf[N48_P87_DUMP_LINE / 4u];
static char gP87Hex[2u * N48_P87_DUMP_LINE + 1u];
static __attribute__((noinline)) uint32_t p87_dump(uint64_t arg) {
    uint64_t off = 0ull, fbStart = 0ull, vramSize = 0ull; uint32_t len = 0u;
    if (!navi48_vram_aperture(fbStart, vramSize)) vramSize = 0ull;
    const uint32_t d = n48_p87_dump_plan(arg, hw_cm_armed() || gXdShot.cont ? 1u : 0u, vramSize, &off, &len);
    HWLOG(N48_P87_REF_FMT, (unsigned long long)off, len, n48_p87_dump_name(d));
    if (d != N48_P87_D_OK) { gP87.dumpRefused++; return d; }
    const uint32_t no = ++gP87.dumps;
    const uint32_t lines = (len + N48_P87_DUMP_LINE - 1u) / N48_P87_DUMP_LINE;
    HWLOG(N48_P87_HDR_FMT, no, gP87.gtag, (unsigned long long)off, len, gP87.gw, gP87.gh, gP87.gbpp, gP87.gsw, lines);
    uint32_t fnv = 2166136261u, fails = 0u;
    static const char hx[] = "0123456789abcdef";
    for (uint32_t at = 0u; at < len; at += N48_P87_DUMP_LINE) {
        const uint32_t n = (len - at < N48_P87_DUMP_LINE) ? len - at : N48_P87_DUMP_LINE;   // len is a multiple of 256: n is 128
        const uint8_t *b = reinterpret_cast<const uint8_t *>(gP87Buf);
        if (!navi48_vram_read_mm(off + at, gP87Buf, n / 4u)) {
            fails++;
            for (uint32_t k = 0; k < n / 4u; k++) gP87Buf[k] = 0u;
        }
        for (uint32_t k = 0; k < n; k++) { gP87Hex[2u * k] = hx[b[k] >> 4]; gP87Hex[2u * k + 1u] = hx[b[k] & 15u]; }
        gP87Hex[2u * n] = '\0';
        fnv = n48_p87_fnv(fnv, b, n);
        HWLOG(N48_P87_HEX_FMT, no, at, gP87Hex);
    }
    HWLOG(N48_P87_END_FMT, no, len, fails, fnv);
    return N48_P87_D_OK;
}
// =============================================================================================================================
// build 0.0.524 item 4 (notes/design/T0SRC.md) — SWITCH 79's PER-FRAME PROBE of S's texture 0, READ-ONLY. Called
// at the end of gfxsrc_c88_frame_end, so only on a B1 frame (the content gate and its per-target budget), and under its own cap of
// N48_T0_LINES line pairs. (a) the first and last page through THIS frame's own page tables, with the sys bit (a system page is
// never a VRAM key); (b) 16 MM-window reads of 64 dwords at P (C1: timed, only under 79, only on these capped frames); (c) the
// producer ledger (gXdLed), (d) the R5' hazard set (t0src_hz: n48_hz_probe / n48_hz_count on a const set, no counter moves),
// (e) the residency-provenance table (gXdRp) - all by the page; (f) the newest map and unmap covering the VA and one other context
// that mapped the same memory object. Under gXdLock like the pass. It writes only its own statics (gT0Lines, gT0S, gT0Buf) and the
// log: no register, no page table, no VRAM, nothing of Apple's and nothing any rule reads.
// =============================================================================================================================
static void t0src_hz(uint64_t page, uint32_t *filt, uint64_t *hits, uint32_t *exact, uint64_t *namer, uint64_t *va);   // beside gR5Ring
static uint32_t gT0Lines { 0u };
static struct { uint64_t reads, readFail, us, usMax, torn; } gT0S {};
static uint32_t gT0Buf[64];   // one MM read (256 B): a file-scope static, under gXdLock like the pass
static __attribute__((noinline)) void gfxsrc_t0src_probe(const GfxcVm &vm) {
    if (!gT0On) return;                                   // C1: only under 79 ...
    const uint32_t ln = n48_t0_take_line(&gT0Lines);      // ... and only on the capped frames
    if (!ln) return;
    const uint64_t va = gC88F.va[0];
    const uint32_t *r0 = gC88F.rec[0];
    const uint64_t vaN = (va + n48_t0_tex_bytes(r0, xlat12_format_elem_bytes((r0[1] >> 20) & 0x1FFu)) - 1ull) & ~0xfffull;
    // (a)
    uint64_t pg0 = 0ull, pgN = 0ull, off0 = 0ull, offN = 0ull;
    bool sys0 = false, sysN = false, ok0 = false, okN = false;
    const bool w0 = gfxc_page(vm, va & ~0xfffull, pg0, sys0), wN = gfxc_page(vm, vaN, pgN, sysN);
    if (w0 && !sys0) off0 = vmib_to_vram_off(pg0, vm.fbStart, vm.vramSize, ok0);
    if (wN && !sysN) offN = vmib_to_vram_off(pgN, vm.fbStart, vm.vramSize, okN);
    const uint32_t c0 = n48_t0_pg_class(w0 ? 1u : 0u, sys0 ? 1u : 0u, ok0 ? 1u : 0u);
    const uint32_t cN = n48_t0_pg_class(wN ? 1u : 0u, sysN ? 1u : 0u, okN ? 1u : 0u);
    const uint32_t use0 = n48_t0_pg_usable(c0);
    uint64_t barPhys = 0ull, barSize = 0ull;
    const uint32_t bar = (use0 && navi48_bar0_aperture(barPhys, barSize) && off0 < barSize) ? 1u : 0u;
    // (b)
    uint32_t zero = N48_T0_ZERO_UNREAD, d0 = 0u, d1 = 0u, d2 = 0u, d3 = 0u;
    if (use0) {
        uint64_t t0 = 0ull, t1 = 0ull, ns = 0ull;
        uint32_t z = 0u, i = 0u;
        clock_get_uptime(&t0);
        for (; i < 16u; i++) {
            gT0S.reads++;
            if (!navi48_vram_read_mm(off0 + (uint64_t)i * 64u * 4u, gT0Buf, 64u)) { gT0S.readFail++; break; }
            if (!i) { d0 = gT0Buf[0]; d1 = gT0Buf[1]; d2 = gT0Buf[2]; d3 = gT0Buf[3]; }
            z += n48_t0_zeros(gT0Buf, 64u);
        }
        clock_get_uptime(&t1);
        absolutetime_to_nanoseconds(t1 - t0, &ns);
        gT0S.us += ns / 1000ull;
        if (ns / 1000ull > gT0S.usMax) gT0S.usMax = ns / 1000ull;
        if (i == 16u) zero = z;
    }
    // (c) (d) keyed by the walked page (the ledger's and the hazard set's own key); (e) by its VRAM offset
    uint32_t ledTok = 0u, hzF = 0u, hzEx = 0u;
    uint64_t ledVa = 0ull, ledCtx = 0ull, hzHits = 0ull, hzNamer = 0ull, hzVa = 0ull, rpVa = 0ull;
    const uint32_t led = use0 ? n48_t0_led_probe(&gXdLed, pg0, &ledTok, &ledVa, &ledCtx) : 0u;
    if (use0) t0src_hz(pg0, &hzF, &hzHits, &hzEx, &hzNamer, &hzVa);
    const uint32_t rp = use0 ? n48_t0_rp_probe(&gXdRp, off0, &rpVa) : 0u;
    HWLOG(N48_T0_FMT, (unsigned long long)gC88F.frame, (unsigned long long)va, n48_t0_pg_prefix(c0),
          (unsigned long long)(use0 ? off0 : pg0), n48_t0_pg_prefix(cN), (unsigned long long)(n48_t0_pg_usable(cN) ? offN : pgN), bar,
          zero, d0, d1, d2, d3, led, ledTok, (unsigned long long)ledVa, hzF, (unsigned long long)hzHits, hzEx, (unsigned long long)hzNamer,
          (unsigned long long)hzVa, rp, (unsigned long long)rpVa, ln);
    // (f)
    static n48_t0_map mp, mo;
    static n48_t0_unmap um;
    uint32_t torn = 0u;
    mp = n48_t0_map {}; mo = n48_t0_map {}; um = n48_t0_unmap {};
    (void)n48_t0_map_newest(&gT0Map, va, &mp, &torn);
    (void)n48_t0_unmap_newest(&gT0Unmap, va, &um, &torn);
    (void)n48_t0_map_other(&gT0Map, mp.mem, mp.ctxSeq, &mo, &torn);
    gT0S.torn += torn;
    HWLOG(N48_T0_MAP_FMT, (unsigned long long)gC88F.frame, (unsigned long long)mp.seq, mp.ctxSeq, mp.pid,
          (unsigned long long)mp.up_ms, (void *)(uintptr_t)mp.mem, mp.seq ? n48_t0_cls_name(&gT0Cls, mp.cls) : "-",
          (unsigned long long)mp.memLen, (unsigned long long)mp.off, (unsigned long long)mp.size, mp.flags, mp.rc8, mp.mem0c,
          (unsigned long long)um.up_ms, (unsigned long long)um.size, mo.ctxSeq, mo.pid, (unsigned long long)mo.va, torn, ln);
}
// After the policy pass: this frame's S lines (B1) and the watch on S's first input (B2). noinline: gfxsrc_decide_frame's frame
// does not carry its locals.
static __attribute__((noinline)) void gfxsrc_c88_frame_end(const GfxcVm &vm, const n48_xv_frame *f, uint32_t ctxSeq) {
    if (gC88F.frame != gXpD4Frame.judged || !gC88F.n || gC88F.printed) return;
    gC88F.printed = 1u;
    // build 0.0.513: the line cap and the watch slots are spent only on the producer's shape 8736|14352
    // (n48_c88_take_frame); an S draw in any other frame (the early pre-arm ones) prints nothing and arms nothing.
    // build 0.0.521 Part B: the gate is the CONTENT scan's answer for this frame, not its IB shape.
    if (!n48_c88_take_frame(&gC88Lines, (gC88Ct.frame == gC88F.frame && gC88Lines < N48_C88_LINES) ?
                                            gfxsrc_c88_producer_take(N48_C88_TGT_K_B1, N48_C88_TGT_B1) : 0u)) return;
    gC88Last = gC88F.frame;
    int widx = -1;
    {   // B2: the watch on texture 0's surface (the first two distinct surfaces per boot)
        const uint32_t *r0 = gC88F.rec[0];
        const uint32_t eb = xlat12_format_elem_bytes((r0[1] >> 20) & 0x1FFu);
        const uint64_t ext = n48_c88_extent(r0, eb);
        uint64_t vram = 0ull;
        const int vok = gfxsrc_rp_walk(&vm, gC88F.va[0], &vram);
        uint32_t idx = N48_C88_WATCH;   // build 0.0.524 item 6: a full table leaves idx unset, so it must print -1, not 0
        const uint32_t added = navi48_c88_watch_add(ctxSeq, gC88F.va[0], ext, vram, vok ? 1u : 0u, &idx);   // 0.0.546: its context
        if (added || idx < N48_C88_WATCH) {
            uint32_t n = 0u; navi48_c88_watch_state(&n, nullptr, nullptr, nullptr, nullptr);
            if (idx < n) widx = (int)idx;
        }
        if (added)
            HWLOG(N48_C88_ADD_FMT, idx, 0u, (unsigned long long)gC88F.va[0], (unsigned long long)ext,
                  (uint32_t)((((r0[1] >> 30) & 3u) | ((r0[2] & 0x3FFFu) << 2)) + 1u), (uint32_t)(((r0[2] >> 14) & 0xFFFFu) + 1u), eb,
                  (unsigned long long)vram, vok ? " (its first page, through this frame's own page tables)" : " - VRAM UNRESOLVED (MM-window writes not watched)");
    }
    for (uint32_t i = 0; i < gC88F.n && i < N48_C88_TEX; i++) {
        const uint32_t *r = gC88F.rec[i];
        HWLOG(N48_C88_FMT, (unsigned long long)gC88F.frame, f->nib > 0u ? f->ib[0].len : 0u, f->nib > 1u ? f->ib[1].len : 0u,
              f->nib > 2u ? f->ib[2].len : 0u, f->nib, (unsigned long long)gC88F.wall_s, gC88F.wall_us, (unsigned long long)gC88F.up_ms,
              gC88F.seg, gC88F.at[i], (unsigned long long)gC88F.cb0, gC88F.tex[i], (unsigned long long)gC88F.va[i],
              r[0], r[1], r[2], r[3], r[4], r[5], r[6], r[7], i == 0u ? widx : -1, gC88Lines, N48_C88_LINES);
    }
    gfxsrc_t0src_probe(vm);   // build 0.0.524 item 4 (switch 79): after the walk and the B1 lines, B1 frames only
}
