    gXdBuild.ok = 0; gXdBuild.nseg = 0; gXdBuild.n = n;
    for (uint32_t z = 0; z < N48_XV_MAX_SEGS; z++) gRectFbSeg[z] = 0u;   // build 0.0.547 (switch 105): this pass's own
    for (uint32_t z = 0; z < N48_XV_MAX_SEGS; z++) gPws93SegConv[z] = 0u;   // build 0.0.537 fix round item 1: this pass's own
    gXdBuild.nsegPre = 0u; gXdBuild.units = 0u;   // build 0.0.481: cleared with nseg (F2, the census label)
