    // prove. Cleared here on every frame, exactly like `seg[]` below: a stale acceptance must never describe a new frame.
    gXdBuild.kind = N48_CM_KIND_UNSET; gXdBuild.hlIbSegments = 0; gXdBuild.hlOk = 0; gXdBuild.hlTotal = 0;
    gXdBuild.lutPlane = 0u;   // 0.0.401: a stale plane verdict must never describe a new frame
    gXdBuild.fill = 0u;       // 0.0.404: nor may a stale fill identity make a plane frame a reservable fill
    gXdBuild.plane = 0u;      // 0.0.420 (P1): nor may a stale plane identity make a filler frame a reservable plane
    gXdBuild.segDraws = 0u;   // 0.0.438: nor may a stale draw count vouch for a new frame
    gXdBuild.md_ok = 0u; gXdBuild.md_clause = 0u; gXdBuild.md_detail = 0ull;   // R1 (D4-PRIME.md item C): cleared at the pass top
    gXdBuild.csElided = 0u;   // build 0.0.487: a previous frame's elision never describes this one
    gXdBuild.drawElided = 0u; // build 0.0.500: nor switch 66's
    gXdBuild.deRows = gDrawElideOn & 0x7u;   // build 0.0.500 (switch 66): read ONCE per pass, like 57 below; 0.0.512: 0x7 (M 7, glass)
    gXdBuild.deRows = n48_an110_rows(an110_mode(), gXdBuild.deRows);   // build 0.0.552 (switch 110): AN's bit, only beside 66's rows
    gUnitState.pack = gUnitPackOn ? 1u : 0u;  // build 0.0.501 (switch 67): read ONCE per pass, before any unit or retry
    gfxsrc_spill_begin(arm, dp);              // build 0.0.522 (switch 76): read ONCE per pass, before any unit or retry
    gXdBuild.xib = gXibOn & N48_MIB_XIB_MASK; gXdBuild.leadMask = 0u;   // build 0.0.505 (switch 69): read ONCE per pass
