    gXdRes.frameDesc = 0;                                 //: this frame's descriptor evidence starts empty
    gXdRes.descPortOn = dp ? 1u : 0u;                     // M4-DESC-KEXT-PORT: 0 unless the switch is on
    dctx.vm = &vm; dctx.ctx = dctxKey;
    if (polTarget) { clock_get_uptime(&polT0); gPolDescTarget = polTarget; }   //(c): setup begins here
    uint32_t ns = 0;
