        if (gXdPairPre) { ex.flags |= XLAT12_EXTRA_PAIR_PRE; gXdPairPreS.segsOn++; }
        // D4' (D4-PRIME.md item 3): OFF (the default and the boot value) this is one volatile load per segment and
