// =============================================================================================================================
// build 0.0.550 ( PLAN step 2; gfx_r3hit.h) - THE R3 HAZARD-HIT INSTRUMENT. LOG-ONLY, EVERY MODE, NO SWITCH. The
// namer identity table beside gR5Ring.hz's exact rows (filled after every n48_r5_note_counted), and the per-frame hit lines for a
// frame whose R3 clause answered R3-neutered-write-destination. n48_hz_probe and n48_hz_count only: the set's own queries/hits
// counters and every decision are untouched. Under gXdLock like the note site and gfxsrc_cprov_eval.
// =============================================================================================================================
static n48_r3_id gR3Id[N48_HZ_ROWS];
static n48_r3h_cap gR3Cap {};
static struct { uint32_t used, seq; } gR3Pre {};
static __attribute__((noinline)) void r3_id_pre(void) { gR3Pre.used = gR5Ring.hz.used; gR3Pre.seq = gR5Ring.hz.arm_seq; }
static __attribute__((noinline)) void r3_id_post(int32_t pid, uint64_t key, uint64_t cb0, uint32_t len0, uint32_t nib, uint32_t verdict)
{
    n48_r3_id id {};
    id.frame = gXdC.judged + 1u; id.key = key; id.cb0 = cb0; id.pid = pid; id.len0 = len0; id.nib = nib; id.verdict = verdict;
    n48_r3_id_note(gR3Id, gR3Pre.used, gR3Pre.seq, gR5Ring.hz.used, gR5Ring.hz.arm_seq, &id);
}
static __attribute__((noinline)) void r3_hit_note(const uint64_t *ptr, const uint64_t *pg, uint32_t n)
{
    if (!ptr || !pg) return;
    const uint64_t fr = gXdC.judged + 1u;
    for (uint32_t i = 0u; i < n; i++) {
        if (!pg[i] || !n48_hz_probe(&gR5Ring.hz, pg[i])) continue;
        uint32_t exact = 0u;
        const uint64_t hits = n48_hz_count(&gR5Ring.hz, pg[i], &exact);
        const uint32_t row = n48_r3_row_of(&gR5Ring.hz, pg[i]);
        gR3Cap.hits++;
        if (exact) gR3Cap.exact++; else gR3Cap.filter_only++;
        if (!n48_r3h_take(&gR3Cap, gR5Ring.hz.arm_seq, fr)) continue;
        const n48_hz_row *r = row < N48_HZ_ROWS ? &gR5Ring.hz.row[row] : nullptr;
        const n48_r3_id *id = (row < N48_HZ_ROWS && gR3Id[row].valid) ? &gR3Id[row] : nullptr;
        HWLOG(N48_R3H_FMT, (unsigned long long)fr, i, n, (unsigned long long)ptr[i], (unsigned long long)pg[i],
              exact ? "EXACT row" : "FILTER-ONLY (both filter bits set, no exact row)", (unsigned long long)hits,
              (unsigned long long)(r ? r->va : 0ull), (unsigned long long)(r ? r->namer : 0ull),
              id ? "identity" : "no identity", id ? id->pid : -1, (unsigned long long)(id ? id->key : 0ull),
              (unsigned long long)(id ? id->cb0 : 0ull), id ? id->len0 : 0u, id ? id->nib : 0u, id ? id->verdict : 0u,
              (unsigned long long)gR3Cap.hits, (unsigned long long)gR3Cap.exact, (unsigned long long)gR3Cap.filter_only,
              (unsigned long long)gR3Cap.suppressed);
    }
}
