// build 0.0.541 - switch 98 (the provenance-ask walk cache). gfx_wc98.h's formats, bounded by tests/gfx_wc98_test.cpp. The verb
// prints the counters since the switch was last set; the CONTINUOUS STOP prints this arm's deltas (nothing while OFF).
static void wc98_report_line(const char *how)
{
    HWLOG(N48_WC_FMT, N48_WC_ARGS(__atomic_load_n(&gWc98Mode, __ATOMIC_RELAXED), how, &gWc.st));
    HWLOG(N48_WC_GEN_FMT, N48_WC_GEN_ARGS(&gN48WcGen));
}
// The CONTINUOUS START (beside pf_arm_start, under gXdLock): the snapshot the STOP subtracts. OFF: nothing.
static __attribute__((noinline)) void wc98_arm_start()
{
    if (__atomic_load_n(&gWc98Mode, __ATOMIC_RELAXED) == N48_WC_OFF) { gWcArmSnapValid = 0u; return; }
    gWcArmSnap = gWc.st;
    gWcCenSnap = gWc.cen;   // build 0.0.543 item B (switch 101): the census's START snapshot, with 98's
    gWcArmSnapValid = 1u;
}
// The CONTINUOUS STOP (beside pf_arm_stop): this arm's deltas and the generation's bumps. OFF: nothing.
static __attribute__((noinline)) void wc98_arm_stop()
{
    const uint32_t m = __atomic_load_n(&gWc98Mode, __ATOMIC_RELAXED);
    if (m == N48_WC_OFF) return;
    n48_wc_st d {};
    const n48_wc_st z {};
    n48_wc_sub(&d, &gWc.st, gWcArmSnapValid ? &gWcArmSnap : &z);
    HWLOG(N48_WC_FMT, N48_WC_ARGS(m, gWcArmSnapValid ? " - CONTINUOUS STOP: this arm's deltas" : " - CONTINUOUS STOP: no START snapshot, totals", &d));
    HWLOG(N48_WC_GEN_FMT, N48_WC_GEN_ARGS(&gN48WcGen));
    // build 0.0.543 item B (switch 101): the census's deltas, right after 98's STOP lines; nothing while the census is OFF.
    if (__atomic_load_n(&gWc.census, __ATOMIC_RELAXED)) {
        n48_wc_cen dc {};
        const n48_wc_cen zc {};
        n48_wc_cen_sub(&dc, &gWc.cen, gWcArmSnapValid ? &gWcCenSnap : &zc);
        HWLOG(N48_WC_CEN_FMT, N48_WC_CEN_ARGS(1u, gWcArmSnapValid ? " - CONTINUOUS STOP: this arm's deltas" : " - CONTINUOUS STOP: totals", &dc));
        HWLOG(N48_WC_CEN_FMT2, N48_WC_CEN_ARGS2(&dc, &gN48WcGen));
    }
    gWcArmSnapValid = 0u;
}
