            if (tgtN > hHeld) gXdDepArmTrunc += tgtN - hHeld;
            n48_cp_frame cf {};
            cf.ctx = fctx;
            // 0.0.393: WAS THIS SUBMISSION POSITIVELY READ AS OUTSIDE THE CONSUMER'S ADDRESS
