            // asked of nothing - the fail-OPEN named as gap A and confirmed.
            cf.complete = (walkOk && pgmOk && !scanOverFrame && !cf.has_dispatch && cf.ntgt <= N48_CP_TGT_MAX) ? 1u : 0u;
            n48_cp_note(&gXpRing, &cf);
